package com.ascent.climb.data.i18n

/**
 * Svenska lektionsnyckelpunkter (47 lektioner / 215 poster).
 * Översatt från kinesiska; terminologi enligt I18N-PLAN.md, avsnitt 5.
 */
internal val PACK_SV_BRIEF: Map<String, String> = mapOf(

    // ---------- l13 Akut höjdsjuka (AMS) ----------
    "lesson.l13.brief.1" to "Diagnoskriterier (Lake Louise): huvudvärk efter en nylig höjdökning, plus minst ett av följande — illamående eller kräkningar, yrsel, trötthet, sömnstörning.",
    "lesson.l13.brief.2" to "När det kommer: oftast 6–12 timmar efter ankomst till höjd. Ju högre, desto vanligare. Mellan 2 500 och 4 300 m insjuknar cirka 25–43 %, under 2 500 m är det ovanligt.",
    "lesson.l13.brief.3" to "Gyllene regeln: vid symtom, fortsätt inte uppåt; vid försämring, gå ner direkt. Det är det enda beslut som aldrig blir fel.",
    "lesson.l13.brief.4" to "Förstå läkemedlen rätt: smärtstillande lindrar huvudvärken, men att symtomen försvinner betyder inte att du är acklimatiserad. Att ta «det gör inte ont längre» som «jag kan fortsätta upp» är ett klassiskt och dödligt fel.",

    // ---------- l14 HACE och HAPE ----------
    "lesson.l14.brief.1" to "HACE (höjdhjärnödem): förändrat medvetande, ostadig gång (misslyckas med häl-tå-testet på linje), dåsighet, avvikande beteende. Ett akut internt tillstånd som kan döda inom timmar.",
    "lesson.l14.brief.2" to "HAPE (höjdlungödem): andnöd även i vila, torrhosta som övergår i skummigt slem, blåaktiga läppar, snabbt fallande prestationsförmåga. HAPE är den vanligaste dödsorsaken vid höjdsjuka.",
    "lesson.l14.brief.3" to "Grundbehandlingen för båda är omedelbar nedstigning. Som stöd: syre, hyperbarisk påse (Gamow), läkemedel.",
    "lesson.l14.brief.4" to "Vanliga läkemedel (endast enligt läkare): dexametason vid HACE och måttlig till svår AMS, vuxna 4 mg var 6:e timme; vid HAPE nifedipin eller PDE-hämmare. Läkemedlet köper tid, det ersätter inte nedstigning.",

    // ---------- l15 Acklimatiseringstakt och läkemedel ----------
    "lesson.l15.brief.1" to "Grundtakt: undvik att sova över 2 750 m samma dag. Över 3 000 m, begränsa hur mycket sovhöjden ökar till 500 m per dag och lägg in en vilodag ungefär var 1 000:e meter.",
    "lesson.l15.brief.2" to "Gå högt, sov lågt: stig på dagen för att acklimatisera dig och gå ner och sov. Det är effektivare än att stanna kvar högt hela tiden.",
    "lesson.l15.brief.3" to "Acetazolamid för förebyggande bruk, oftast från dagen före uppstigningen, 125 mg två gånger dagligen för vuxna. Receptbelagt, följ läkarordination.",
    "lesson.l15.brief.4" to "Icke-farmakologiska åtgärder fungerar lika bra: drick tillräckligt, ät mest kolhydrater, undvik alkohol och lugnande medel, skydda sömnkvaliteten.",

    // ---------- l16 Hypotermi och förfrysning ----------
    "lesson.l16.brief.1" to "Grad av hypotermi: lindrig (frossa, klar) → måttlig (frossan upphör, förvirring, sluddrigt tal) → svår (koma, svag puls och andning).",
    "lesson.l16.brief.2" to "Det vanligaste felet: att frossan upphör är inte bättring utan försämring. Det är här många vänder på bedömningen.",
    "lesson.l16.brief.3" to "Vid måttlig hypotermi eller värre: flytta inte hårt och låt inte extremiteterna arbeta hårt; det kalla hjärtat får lätt arytmi. Värm bålen först, inte händer och fötter.",
    "lesson.l16.brief.4" to "Återuppvärmning av förfrysning: sänk i vatten på 37–40 °C i cirka 30 minuter tills huden blir röd och mjuk. Aldrig gnugga med snö, aldrig hålla vid eld, aldrig värmedyna direkt mot huden.",
    "lesson.l16.brief.5" to "Om risk för återfrysning finns, värm inte på plats — skadorna efter återfrysning är mycket värre än en enkel nedfrysning. Gå ner med skadan. Spräck inte blåsor.",

    // ---------- l17 Grundläggande isklättring ----------
    "lesson.l17.brief.1" to "Isyxan slås med handleden, inte med hela armen. Spetsen går in vertikalt; ett torrt «klack» betyder bra fäste, ett dovt ljud oftast fel vinkel eller murken is.",
    "lesson.l17.brief.2" to "Spark: böj knäet, lyft foten, driv in framtänderna vertikalt. Stabilisera båda fötterna innan du slår, håll trepunktstakten — flytta fjärde punkten först när tre sitter.",
    "lesson.l17.brief.3" to "WI-grader: WI1 låg vinkel, gångbart; WI2 cirka 60° med bulor och bra säkring; WI3 ihållande 60–75°, fysiskt krävande; WI4 nästan vertikalt med korta vertikala passager, säkringen kan vara dålig.",
    "lesson.l17.brief.4" to "WI5 är ihållande vertikalt med dålig och påfrestande säkring; WI6 är vertikalt med överhäng och mycket dålig säkring. Ju högre grad, desto mindre marginal för reträtt och självräddning.",
    "lesson.l17.brief.5" to "Isklättring beror starkt på isens skick och din form, och kräver säkring underifrån av någon erfaren. Isen ändras varje dag; gårdagens grad kan vara en helt annan i dag.",

    // ---------- l18 Laviner grunderna ----------
    "lesson.l18.brief.1" to "Lutningen är den starkaste enskilda prediktorn: cirka 96 % av lavinerna går på 30–50° sluttningar, de flesta mellan 34 och 45°.",
    "lesson.l18.brief.2" to "Under cirka 30° är det för flackt för flaklaviner; över cirka 50° samlas snön dåligt och tjocka flak är ovanliga. Sluttningen som «inte ser så brant ut» är farligast.",
    "lesson.l18.brief.3" to "Farlighetsgrader 1–5: låg / måttlig / betydande / stor / mycket stor. Statistiskt samlas olyckorna på grad 3, betydande — terrängen ser rimlig ut och underskattas lättast.",
    "lesson.l18.brief.4" to "Lavintrion måste bäras och behärskas: transceiver, sond, spade. Utan utrustning och begravd är överlevnadsfönstret cirka en kvart.",
    "lesson.l18.brief.5" to "I lavinterräng: håll avstånd, passera en i taget, sätt ut en vakt och planera flyktvägen — så att hela gruppen aldrig begravs samtidigt.",

    // ---------- l19 Planering och vändbeslut ----------
    "lesson.l19.brief.1" to "Sätt en vändtid: när den är inne vänder man, hur nära toppen det än är. Det är den mest effektiva hårda regeln i bergen.",
    "lesson.l19.brief.2" to "Toppen är bara halva resan. Många olyckor sker på nedvägen: uppmärksamheten sjunker när målet är nått medan orken redan är nära gränsen.",
    "lesson.l19.brief.3" to "Toppfeber förvränger omdömet systematiskt: sjunkna kostnader, grupptryck, målfixering och ovilja att ge upp «efter att ha kommit så långt». Den skonar inte erfarenhet — guider och veteraner drabbas också.",
    "lesson.l19.brief.4" to "Kom överens om reträtten i förväg: vem har rätt att säga stopp? Vilka objektiva signaler utlöser den (tid, väderfönster, gruppens skick, snöläget)? Bestämt i förväg kan känslorna inte kapa beslutet på plats.",

    // ---------- l20 Nödsituation och räddning ----------
    "lesson.l20.brief.1" to "Ordning vid nödsituation: säkra platsen → bedöm skadade (luftvägar, andning, cirkulation, medvetande) → larma → grundvård (värme, blodstillning, spjälsa) → flytta eller invänta professionell räddning.",
    "lesson.l20.brief.2" to "Första principen: skapa inte en andra skadad. Varje räddningsinsats får bara ske om du och resten av gruppen är säkra.",
    "lesson.l20.brief.3" to "Räddning på höjd begränsas hårt av väder, syre, kommunikation och personal, och tar ofta timmar till dygn. Just därför är förebyggande långt mer värt än räddning.",
    "lesson.l20.brief.4" to "Lämna före avfärd en detaljerad rutt och en kontakt, och känn till lokala räddningsresurser och kommunikationsmöjligheter (satellit, radio, nödfrekvenser). Utan kommunikation finns inget larm.",

    // ---------- l21 Tre lager ----------
    "lesson.l21.brief.1" to "Tre lager, tre uppgifter: innerlagret transporterar bort svett, mellanlagret isolerar, ytterlagret stänger ute vind och regn. Inget ersätter ett annat; blandning försämrar båda.",
    "lesson.l21.brief.2" to "Innerlagret får aldrig vara bomull: det suger svett och torkar nästan inte, och fuktig kyla mot huden fortsätter stjäla värme. Välj polyester eller merinoull med snabb fukttransport.",
    "lesson.l21.brief.3" to "Fleece i polyester är naturligt vattenavvisande och isolerar även vått — därför är det pålitligare än dun i fukt och används ofta som mellanlager.",
    "lesson.l21.brief.4" to "Dunjacka från cirka 800 fill power; för extrem kyla modell med huva och utan syntetfyllning. Dun isolerar mycket effektivt men förlorar nästan all förmåga när det blir blött.",
    "lesson.l21.brief.5" to "Ytterskalet (Gore-Tex-jacka och byxor) ger vattentäthet, vindskydd och andning; kontrollera kompatibilitet med hjälm. Damasker hindrar snö från att komma in i kängorna, på höjd hellre långa.",

    // ---------- l22 Teknisk utrustning ----------
    "lesson.l22.brief.1" to "Utrustning för uppstigning och säkring: greppyxa, skruvkarbin, karbin utan skruv, åtta eller ATC-tub, 120 cm sling.",
    "lesson.l22.brief.2" to "Prusikslingan är grunden för räddning ur spricka: den används för friktionsknut och är kärnan i 3:1-systemet. Ska alltid bäras på kroppen.",
    "lesson.l22.brief.3" to "Navigering och kommunikation: höjdmätarklocka (med barometer och stormvarning), GPS-tracker, satellittelefon. I fjällen finns ingen mobiltäckning; satellit är ofta enda sättet att larma.",
    "lesson.l22.brief.4" to "Ljus: pannlampan måste kunna fästas på hjälmen; reservlampan helst över 400 lumen (500-lumensmodeller är klart bättre i dåligt väder), och vädertålig.",
    "lesson.l22.brief.5" to "Selan måste sitta även över det yttersta klädlagret; välj stora karbiner med skruv, de är lättare att hantera med handskar.",

    // ---------- l1 Förstå riskerna ----------
    "lesson.l1.brief.1" to "Farorna i högfjället är av två slag. Objektiva faror ändras inte med din teknik: stenfall, isfall, laviner, väderomslag, sprickor. Subjektiva faror styr du: felbedömningar, bristande förberedelse, utmattning, jämförelse och toppfixering.",
    "lesson.l1.brief.2" to "Utbildning minskar de subjektiva farorna. Objektiva faror går inte att undvika, bara att gå runt, välja rätt tillfälle och hålla en reträttväg öppen.",
    "lesson.l1.brief.3" to "Temperaturen sjunker i snitt cirka 6,5 °C per 1 000 m; lufttryck och syrepartialtryck faller samtidigt. Det är roten till höjdsjuka.",

    // ---------- l2 Isyxa och stegjärn ----------
    "lesson.l2.brief.1" to "Två typer av isyxa. Typ B (bas) med ganska rakt skaft, för snövandring och självstopp; typ T (teknisk) med skaft som kan sättas i isen och ta drag, för branta isväggar och teknisk klättring.",
    "lesson.l2.brief.2" to "Tre klasser av stegjärn: C1 helt med remmar, C2 rem fram och klick bak, C3 helt klick. Högre klass ger styvare, men ställer högre krav på kängan.",
    "lesson.l2.brief.3" to "Känga och stegjärn måste passa ihop: B1 mjuk med C1, B2 halvstyvt med C2, B3 styvt med C3. Det är en säkerhetsgräns, inte en smaksak.",

    // ---------- l3 Kängor och utrustning ----------
    "lesson.l3.brief.1" to "Enkellagerskängor är lätta och smidiga, för medelhöjd och isklättring; dubbellagers (löstagbar innersko) isolerar bättre och torkar, för extrem kyla och flerdagarsturer.",
    "lesson.l3.brief.2" to "Kängan måste passa stegjärnen och inte trycka tårna framtill. På nedvägen glider foten fram: för liten storlek skadar naglar och tåben.",
    "lesson.l3.brief.3" to "Snöglasögon är nödvändiga, inte tillbehör: snön reflekterar UV starkt och kan ge snöblindhet och allvarliga brännskador. Välj UV400.",
    "lesson.l3.brief.4" to "Ta med två par handskar (tjocka för värme, tunna för känsla), isolerande lager ska vara vattentätt, och reservkläder alltid väl förslutna.",

    // ---------- l4 Gå på snö ----------
    "lesson.l4.brief.1" to "Sparka steg: slå med kängans kant i hård snö, korta steg, jämn takt, stabilt tyngdpunkt. Ju planare steg, desto lättare för dem som följer.",
    "lesson.l4.brief.2" to "Håll isyxan i handen på sluttningens sida, som käpp (piolet canne): tappar du balansen kan du gå direkt in i bromsställning utan att byta hand.",
    "lesson.l4.brief.3" to "Vid uppstigning, synkronisera tryckandningen med steget: andas in djupt, andas ut hårt, i samma takt som stegen. Det lindrar kvävningskänslan på höjd märkbart.",
    "lesson.l4.brief.4" to "Ha alltid minst två säkra kontaktpunkter; vid sväng, stanna först och vrid sedan, utan att vrida kroppen i rörelse.",

    // ---------- l5 Stegjärnsteknik ----------
    "lesson.l5.brief.1" to "Fransk teknik (flat fot): alla taggar vinkelräta mot marken ligger samtidigt mot sluttningen, foten är plan och framtänderna slår inte. Minst ansträngande, för låg till medelhög lutning och hård snö.",
    "lesson.l5.brief.2" to "Tysk teknik (framtänder): framtänderna drivs in vertikalt, vaden driver. För sluttningar över 45° och isväggar, men mest energikrävande.",
    "lesson.l5.brief.3" to "Amerikansk teknik (blandad): en fot ligger plant, den andra driver med framtänderna, växelvis. För övergångsterräng mellan medel och brant.",
    "lesson.l5.brief.4" to "Vid travers, använd ankgång: hälarna ihop, tårna utåt, så att hela stegjärnet ligger mot sluttningen och inte bara innertaggarna bär.",

    // ---------- l6 Självstopp ----------
    "lesson.l6.brief.1" to "Bromsställning: gå snabbt ner på mage mot sluttningen, isyxan diagonalt framför bröstet; en hand på huvudet (nära spetsen), den andra på skaftet.",
    "lesson.l6.brief.2" to "När spetsen sitter i snön, tryck ner med kroppsvikten: ju hårdare, desto djupare.",
    "lesson.l6.brief.3" to "Ett annat vanligt fel: båda fötterna ska lyftas från snön, tårna uppåt. Så snart en fot rör snön försvinner vikten på isyxan.",
    "lesson.l6.brief.4" to "Om du glider med huvudet före, vänd först över på mage med fötterna nedåt och sätt sedan bromsen.",
    "lesson.l6.brief.5" to "Självstopp är ren muskelminne. Det måste repeteras på mjuk snö med instruktör som säkrar, tills det sitter i ryggmärgen: video och böcker ersätter inte.",

    // ---------- l7 Fall ----------
    "lesson.l7.brief.1" to "Första principen: fall inte. Under gång, säkra dig hela tiden — sätt isyxans skaft i snön som tillfälligt stöd, varje steg behåller ett stöd.",
    "lesson.l7.brief.2" to "Vid förlorad balans: ropa högt «fall!», gå samtidigt ner på mage och ta bromsställning. De tre rörelserna sker nästan samtidigt.",
    "lesson.l7.brief.3" to "Om kamraten faller: sätt först dig själv i bromsställning och sträck repet. Dra inte med handen, då glider oftast båda.",
    "lesson.l7.brief.4" to "Bromsning är att minska farten, inte att stoppa direkt. På brant sluttning och hård snö kan bromssträckan bli över tio meter, så agera tidigt.",

    // ---------- l8 Nedstigning och glidning ----------
    "lesson.l8.brief.1" to "Nedstigningen är ofta farligare än uppstigningen: orken är förbrukad, uppmärksamheten sjunker, tyngdpunkten lutar framåt. Olyckor sker ofta på nedvägen.",
    "lesson.l8.brief.2" to "I teknisk terräng, klättra ner vänd mot sluttningen: ansiktet mot snön, tre stöd, steg för steg. Synfältet är framåt och balansen stabil.",
    "lesson.l8.brief.3" to "Kontrollerad glidning får bara användas utan sprickor, utan stenfall och med fritt utrymme nedanför, och bara om du när som helst kan gå in i självstopp.",
    "lesson.l8.brief.4" to "Under glidningen ska handen alltid hålla isyxans huvud så att den är klar att bromsa: aldrig i ryggsäcken eller på andra sidan kroppen.",

    // ---------- l9 Grundknutar ----------
    "lesson.l9.brief.1" to "Åttaknut med efterföljande: den vanligaste knuten till selan. Lätt att synkontrollera, går att lösa efter belastning; standard på glaciär och blandade rutter.",
    "lesson.l9.brief.2" to "Skotstek: fäster repet i en karbin och kan justeras med en hand; standard för självsäkring vid standplats.",
    "lesson.l9.brief.3" to "Dubbelt fiskarknut: används för att sammanfoga två rep eller göra en prusikslinga.",
    "lesson.l9.brief.4" to "Prusik: friktionsknut. Griper repet under last och glider utan last — för uppstigning, backup och räddningssystem.",
    "lesson.l9.brief.5" to "Lämna tillräcklig ände efter knuten, oftast minst tio gånger repdiametern, och kontrollera varandra. Knutens kvalitet påverkar säkerheten direkt.",

    // ---------- l10 Replag på glaciär ----------
    "lesson.l10.brief.1" to "På glaciär är ett replag på tre idealiskt: faller en i en spricka har de andra två marginal att säkra och rädda. Med två är marginalen liten och risken klart högre.",
    "lesson.l10.brief.2" to "Avståndet är oftast 8–12 m. Knutar mellan sektionerna (fjärilsknut) ökar friktionen i snön och bromsar fallet.",
    "lesson.l10.brief.3" to "Replaget är ingen universalförsäkring. Det förutsätter att kamraterna kan bromsa och säkra. Kan de inte det blir replaget ett gemensamt fall.",
    "lesson.l10.brief.4" to "På glaciär, bär sele hela tiden och ha karbiner, prusikslinga, snöankare och övrig självräddningsutrustning inom räckhåll.",

    // ---------- l11 Standplats SRENE ----------
    "lesson.l11.brief.1" to "SRENE-principen: Solid (stark), Redundant (redundant), Equalized (lastfördelad), No Extension (ingen förlängning).",
    "lesson.l11.brief.2" to "EARNEST är en mer komplett bedömningsram: Efficient (effektiv), Anchored (väl förankrad), Redundant, No Extension, Strong (tillräckligt stark), Timely (snabbt byggd).",
    "lesson.l11.brief.3" to "Provet är enkelt: tar man bort en punkt, håller systemet? Först då är det redundant.",
    "lesson.l11.brief.4" to "Vanliga fästpunkter: i snö snöankare, deadman, T-ränna; i is isskruv. Olika medium kräver helt olika teknik.",

    // ---------- l12 Räddning ur spricka ----------
    "lesson.l12.brief.1" to "Sprickor är glaciärens huvudrisk. Snöbroar kan vara helt täckta av nysnö och syns inte mot en vanlig yta — det är det farligaste.",
    "lesson.l12.brief.2" to "Passera sprickzoner alltid i replag, med repet måttligt sträckt och utan stora häng; annars faller den som faller först fritt och får sedan ett ryck.",
    "lesson.l12.brief.3" to "Standardförfarande när någon faller: kamraten självsäkrar direkt → bygger snöstandplats → flyttar lasten till standplatsen → hissar med mekanisk fördel.",
    "lesson.l12.brief.4" to "Det vanligaste systemet är Z 3:1 (Z-pulley / Z-drag): prusik och trissa på det belastade repet, kombinerat med standplatsen för trefaldig kraft.",
    "lesson.l12.brief.5" to "Den som fallit håller sig lugn, försöker klättra upp på prusik och hindrar repet från att fortsätta skära in i snökanten vid sprickan.",

    // ---------- m01 Vetenskap om fjällmiljön ----------
    "lesson.m01.brief.1" to "Ju högre, desto lägre tryck. Andelen syre i luften ändras knappt, fortfarande cirka 21 %; det är trycket som ändras. Lägre tryck ger färre syremolekyler per andetag. Där är roten till höjdhypoxi: inte mindre syre, utan lägre partialtryck.",
    "lesson.m01.brief.2" to "Temperaturen sjunker cirka 6,5 °C per 1 000 m. Varför snögränsen ligger där den ligger och varför 5 000-meters toppar har snö mitt i sommaren följer av den regeln.",
    "lesson.m01.brief.3" to "Lufttrycket faller ungefär exponentiellt med höjden. På 5 000 m är det ungefär hälften av havsnivån: varje andetag ger bara hälften så många syremolekyler.",
    "lesson.m01.brief.4" to "Höjden tillför tre ofta underskattade faktorer: klart starkare UV (cirka 10–12 % per 1 000 m), extremt torr luft och stark reflektion från snön.",
    "lesson.m01.brief.5" to "Utrustning, gångtakt och förebyggande av höjdsjuka som kommer senare härleds alla från dessa fysikaliska lagar.",

    // ---------- m02 Fysik och näring ----------
    "lesson.m02.brief.1" to "Högfjäll belönar lång, lågintensiv ansträngning — aerob uthållighet. Explosiv styrka är till liten nytta; i hypoxi går den inte att få fram.",
    "lesson.m02.brief.2" to "Träna progressivt och återhämta fullt. Trappa ner de sista 2–3 veckorna före avresa; du ska komma till berget fräsch, inte sliten.",
    "lesson.m02.brief.3" to "På höjd, ät mest kolhydrater. De omsätts effektivare än fett i hypoxi, och kroppen vill ha dem instinktivt. Att följa instinkten är mer realistiskt än att tvinga i sig fet mat.",
    "lesson.m02.brief.4" to "Drick regelbundet i små mängder. En bra indikator är ljus urin; när törsten är tydlig är man ofta redan lätt uttorkad.",
    "lesson.m02.brief.5" to "Alkohol och lugnande medel dämpar andningsdriften och förvärrar nattlig hypoxi — på höjd ska de undvikas helt.",

    // ---------- m03 Miljö och etikett ----------
    "lesson.m03.brief.1" to "Leave No Trace är friluftslivets miljöprincip: håll människans påverkan på fjället så låg som möjligt. Miljöns kapacitet är begränsad och populära rutter utsätts för ständigt tryck.",
    "lesson.m03.brief.2" to "Ta med allt skräp ner — förpackningar, matrester, fimpar och hygienartiklar som toalettpapper. Vänd dig om och kontrollera området innan du lämnar lägret.",
    "lesson.m03.brief.3" to "Avföring ska grävas ner i en grop eller bäras ut, långt från vatten, läger och led. Den mest förbisedda punkten, men den påverkar nästa grupp och vattnets säkerhet direkt.",
    "lesson.m03.brief.4" to "Förvara mat och skräp tätt så att djur inte sprider det; undvik viltområden och deras känsliga perioder (parning, uppfödning).",
    "lesson.m03.brief.5" to "Skada inte vegetation, ta inte med naturföremål, gå på befintliga leder. Nya stigar från tramp består i åratal och orsakar erosion.",

    // ---------- m04 Väder och navigering ----------
    "lesson.m04.brief.1" to "Bedöm vädret på trenden, inte på ögonblicket. Fallande tryck, tätare och lägre moln, ökande vind är tecken på försämring. Att det är sol nu säger lite.",
    "lesson.m04.brief.2" to "Moln är en billig och effektiv prognos: cumulus som växer vertikalt med städsky bildar åska och kraftig nederbörd; sjunkande stratus betyder snabbt sämre sikt.",
    "lesson.m04.brief.3" to "Vanliga kartskalor i fjällen är 1:50 000 och 1:10 000. Täta höjdkurvor betyder brant; en sluten kurva visar en egen topp.",
    "lesson.m04.brief.4" to "Kompass: håll den horisontellt, bort från magnetiska föremål, ta aldrig nålens södra ände för norr (180°-fel), och korrigera för lokal missvisning.",
    "lesson.m04.brief.5" to "Grundfärdigheten är att alltid veta var du är. Korsa karta, kompass och terräng; lita inte bara på GPS. Elektronik tar slut på batteri, blir blöt och går sönder när den tappas.",

    // ---------- m05 Första topparna ----------
    "lesson.m05.brief.1" to "Första snötopparna ligger oftast kring 5 000 m, med vandringsrutter och lite teknik. De verkliga svårigheterna är acklimatisering och väder.",
    "lesson.m05.brief.2" to "Kilimanjaro 5 895 m (Tanzania, Afrikas högsta, toppen Uhuru Peak): från regnskog till glaciär genom flera klimatzoner, ingen teknisk utrustning krävs.",
    "lesson.m05.brief.3" to "Aotaina 5 211 m (officiellt, uppmätt cirka 4 800 m): «bergens son» i Tre Ao-massivet, utan teknisk svårighet och med hög framgång — anses vara en bra första snötopp.",
    "lesson.m05.brief.4" to "Siguniang Shan, stora toppen 5 025 m och andra toppen 5 276 m (Xiaojin, Sichuan): den klassiska nybörjarkombinationen; sista biten på andra toppen kräver enkel teknisk hjälp.",
    "lesson.m05.brief.5" to "För att välja första berget, jämför rutinens mognad, guider och räddningsresurser, höjdtakten och din egen form och tid. Siffran för höjd spelar mindre roll.",

    // ---------- m06 Teknisk klättring: start ----------
    "lesson.m06.brief.1" to "Tre grundsystem: bromsa (självstopp med isyxa), säkra (rep och standplats), förflytta (replag och säkring). Tillsammans gör de ett okontrollerat fall till en hanterbar risk.",
    "lesson.m06.brief.2" to "Teknik lär man sig inte för svårare berg, utan för att pressa risken till en acceptabel nivå i teknisk terräng som inte går att undvika. Viktigare är att kunna avgöra när ingen teknik behövs.",
    "lesson.m06.brief.3" to "Teknik måste övas på plats. Självstopp repeteras på mjuk snö, flack sluttning, fritt utrymme nedanför och med instruktör som säkrar, tills det blir reflex — video och böcker ersätter inte.",
    "lesson.m06.brief.4" to "De tre startutrustningarna är stegjärn, isyxa och sele. Var för sig är de värdelösa; de blir system först med kroppen och kamraten.",
    "lesson.m06.brief.5" to "Teknik är alltid underställd omdömet. Utrustning och rörelser är bara medel; livet avgörs av frågan om man ska gå upp. Nästa avsnitt börjar med de tekniska rörelserna.",

    // ---------- m07 Standplatser och fästpunkter ----------
    "lesson.m07.brief.1" to "Standplatsen förbinder människan med berget och ger fallkraften en väg. Utan standplats är repet bara en ögla.",
    "lesson.m07.brief.2" to "Tre typer av fästpunkter: naturliga (klippspets, stort träd, stort block), i snö (snöankare, deadman, T-ränna), i is (isskruv). Olika medium, helt olika bedömning.",
    "lesson.m07.brief.3" to "Bedöm standplatsen på fyra saker: stark, redundant, lastfördelad, ingen förlängning. De tre sista svarar på samma fråga: vad händer om en punkt ger sig?",
    "lesson.m07.brief.4" to "Vinkeln mellan punkterna ökar lasten markant: vid 0° bär varje punkt cirka 50 %, vid 60° cirka 58 %, vid 90° cirka 71 %. Större vinkel ger tyngre last per punkt.",
    "lesson.m07.brief.5" to "Kort sagt: ger någon punkt sig får systemet inte kollapsa. Det är vad redundant betyder.",

    // ---------- m08 Gangshika och första tekniska ----------
    "lesson.m08.brief.1" to "Gangshika i Menyuan (Qinghai) är högsta toppen i Qilianbergens östra del. Huvudtopp 5 254,5 m, med en sidotopp på 5 150 m och tredje toppen 5 005 m — «tredje → huvudtopp» är en naturlig trappa.",
    "lesson.m08.brief.2" to "Tredje Gangshika är teknisk nybörjarrutt: cirka 10 km ansats, ungefär 6 timmar, cirka 95 % framgång för nybörjare. Bra mål för första kontakten med teknisk utrustning och isiga sluttningar.",
    "lesson.m08.brief.3" to "Haba Xueshan 5 396 m (Shangri-La, Yunnan): isiga sluttningar ovanför snögränsen, stegjärn och isyxa krävs; det vanliga steget från vandring till teknik.",
    "lesson.m08.brief.4" to "Elbrus 5 642 m (Kaukasus, Ryssland): Europas högsta. Stegjärn och isyxa krävs, glaciärgång och replag är grundkrav.",
    "lesson.m08.brief.5" to "Vid steget från vandring till teknik saknas oftast inte kondition, utan handhavande av utrustningen, bromsförmåga och omdömet att veta när man ska vända.",

    // ---------- m09 Läkemedel på höjd ----------
    "lesson.m09.brief.1" to "Höjdmedicin har bara två mål: snabbare acklimatisering (acetazolamid) eller tid till nedstigning (dexametason, nifedipin). Utan den åtskillnaden används fel medel och tillståndet bedöms fel.",
    "lesson.m09.brief.2" to "Acetazolamid: påskyndar acklimatiseringen. 125 mg två gånger dagligen, starta ungefär dagen före uppstigningen och sluta ungefär två dagar efter; utsättning ger ingen återstuds.",
    "lesson.m09.brief.3" to "Dexametason: starkt steroid, sänker intrakraniellt tryck och lindrar hjärnödem, ofta vid HACE. 4 mg var 6:e timme; påverkar inte acklimatiseringen och botar inte lungödem. Vid okontrollerbara kräkningar krävs injektion.",
    "lesson.m09.brief.4" to "Nifedipin: dämpar hypoxins lungkärlssammandragning, för att förebygga och behandla lungödem. 20–30 mg depottablett var 12:e timme; blodtrycket kan falla snabbt och att resa sig hastigt kan ge svimning.",
    "lesson.m09.brief.5" to "Det viktigaste: läkemedlet lindrar symtom men förbättrar inte acklimatiseringen. Även om dexametason tar bort symtomen bör man inte fortsätta uppåt, utan gå ner så snart som möjligt. All användning kräver läkarordination.",

    // ---------- m10 Vädertönster ----------
    "lesson.m10.brief.1" to "Vädertönstret är perioden då målet kan nås säkert. Det avgör starttid, gångtakt och vändtid.",
    "lesson.m10.brief.2" to "Väder på höjd har tre drag: snabba ändringar, stark lokal variation och begränsad prognossäkerhet. Den regionala prognosen ger bakgrunden; för en viss kam eller ett visst pass måste du titta själv.",
    "lesson.m10.brief.3" to "Titta på trenden, inte på värdet: trycket faller stadigt, molnen blir tätare och lägre, vinden ökar. Alla tre samtidigt betyder nästan säkert försämring.",
    "lesson.m10.brief.4" to "Vinden är den mest direkta begränsningen. Beaufortskalan översätter vindhastighet till kännbara steg — den avgör hur stark vind du kan fortsätta i.",
    "lesson.m10.brief.5" to "Det finns också ett dygnsmönster: morgonen är oftast stabilast, på eftermiddagen ökar konvektionen, molnigheten tilltar och risken för åska och nederbörd stiger — därför läggs toppdagen ofta före gryningen.",

    // ---------- m11 6 000-metersberg ----------
    "lesson.m11.brief.1" to "Yuzhu Feng 6 178 m (Golmud, Qinghai, östra Qilian): sydsidan är relativt mild och lättillgänglig; det vanligaste första 6 000-meterberget i Kina.",
    "lesson.m11.brief.2" to "Qizi Feng 6 206 m (Damxung, Tibet, Nyainqêntanglha): stabila snösluttningar, bra tillgänglighet, lämplig träningstopp.",
    "lesson.m11.brief.3" to "Lobuche East 6 119 m (Khumbu, Nepal): precis vid Everesttrekken, brantare snösluttningar, ofta övergång mellan Island Peak och 8 000-metersbergen.",
    "lesson.m11.brief.4" to "Island Peak (Imja Tse) 6 189 m (Khumbu, Nepal): replag och sprickpassage krävs; den klassiska tekniska 6 000-metersberget.",
    "lesson.m11.brief.5" to "Tröskeln på 6 000 m ligger i acklimatiseringen, inte i tekniken. Vid 6 000 m stiger risken för höjdsjuka tydligt; sprickor och laviner är inte längre möjligheter utan något man måste räkna med.",

    // ---------- m12 Avancerade knutar och mekanisk fördel ----------
    "lesson.m12.brief.1" to "Grundknutar löser förbindelsen; avancerade system löser två svårare saker: förstärka kraft och arbeta under last.",
    "lesson.m12.brief.2" to "Mekanisk fördel: Z-systemet 3:1 ger trefaldig dragkraft med prusik och en trissa, standard vid glaciärräddning. Utan trissa går det med karbin, men friktionen ökar och effektiviteten faller.",
    "lesson.m12.brief.3" to "Räddningsutrustning (lärobok): 2–3 snöankare eller isskruvar, 2–5 karbiner, 2–5 sling, 1 trissa, 2–3 prusikar, 1 greppyxa.",
    "lesson.m12.brief.4" to "Greppyxan bromsar med ståltänder och omvänd friktion mot repet, så för hård kraft skadar repet. Använd om möjligt kompletterande säkringsmetod.",
    "lesson.m12.brief.5" to "Systemets värde är att en person klarar vad som annars är omöjligt — men det bygger på kunskap om utrustningen och upprepad övning. Att packa upp systemet på plats är att lära sig använda det på olycksplatsen.",

    // ---------- m13 Självständighet på 7 000 ----------
    "lesson.m13.brief.1" to "Självräddning är den hårda tröskeln på 7 000 m: kamraten kanske inte hinner fram, du måste klara din egen situation.",
    "lesson.m13.brief.2" to "Uppklättring på prusik är grundmetoden för att hålla positionen eller ta sig ur en spricka: två prusikar växelvis, en bär, en flyttas upp.",
    "lesson.m13.brief.3" to "De fyra stegen i replagsräddning (bromsa → bygg standplats → flytta last → hissa) lärdes på 6 000 m; här är målet att utföra dem under press.",
    "lesson.m13.brief.4" to "Uppskatta åskavstånd: tidsskillnad mellan blixt och dunder (sekunder) × 0,34 = avstånd i kilometer. Ljudet färdas cirka 0,34 km/s.",
    "lesson.m13.brief.5" to "Vid åska, håll cirka 50 m mellan varandra så att ett nedslag inte träffar flera; små metallföremål drar inte blixten, slösa inte tid på att kasta dem.",

    // ---------- m14 Riskbedömning och beslut ----------
    "lesson.m14.brief.1" to "Kärnfrågan är inte om det finns fara, utan om risken är acceptabel — det kräver att man översätter den subjektiva känslan till diskuterbara, delbara kriterier.",
    "lesson.m14.brief.2" to "Olyckskedjan: en allvarlig olycka är ofta summan av små misstag (optimistisk bedömning → tidsförskjutning → förenklad säkring → misstag av trötthet). Bryt en länk och olyckan sker inte.",
    "lesson.m14.brief.3" to "Beslutsfällor är oberoende av erfarenhet: sjunkna kostnader (redan investerat mycket), grupptryck (vill inte bromsa), målfixering (bara lite kvar), risknormalisering (förra gången gick det).",
    "lesson.m14.brief.4" to "I riskfylld miljö ska den mest försiktiga rösten prioriteras. Majoritetsbeslut trycker undan en minoritets rimliga oro, och den vanligaste meningen i olycksutredningar är: «någon tyckte att något var fel, men ingen sa det».",
    "lesson.m14.brief.5" to "Konkret åtgärd: kvantifiera kriterierna före avfärd (vändtid, vädertröskel, tillståndströskel), så att en uppmjukning blir en uttalad handling som måste förklaras för gruppen.",

    // ---------- m15 Läsa moln ----------
    "lesson.m15.brief.1" to "Värdet med att läsa moln är försprånget: de är det mest synliga tecknet på väderomslag och syns tidigare än barometern.",
    "lesson.m15.brief.2" to "Cumulus → cumulonimbus är den typiska vägen till åska. Vertikal tillväxt visar stark konvektion; när städskyen bildas är mogen fas nådd och blixt, hagel och kraftig nederbörd är möjliga.",
    "lesson.m15.brief.3" to "Cumulus bildas mest på eftermiddagen när solen värmer marken och skapar konvektion. Att starta tidigt och gå ner i tid är det enklaste åskskyddet.",
    "lesson.m15.brief.4" to "Olika moln betyder olika: linsmoln följer ofta hård vind; tilltagande cirrus (trådiga, högt) aviserar ett närmande system; sjunkande stratus betyder sämre sikt.",
    "lesson.m15.brief.5" to "Molnläsning måste kombineras med trycktrenden: molnen säger hur det är nu, trycket säger vart det är på väg.",

    // ---------- m16 Laviner: avancerad bedömning ----------
    "lesson.m16.brief.1" to "Avancerad bedömning lägger tre skalor ovanpå varandra: regional prognos (bakgrundsrisk), terräng (samlas och släpper det?), snötäcke (stabilitet på plats). Saknas en blir det fel.",
    "lesson.m16.brief.2" to "Lutningen är den starkaste enskilda prediktorn: cirka 96 % av lavinerna mellan 30 och 50°, de flesta 34–45°. Under 30° för flackt, över 50° samlas snön dåligt.",
    "lesson.m16.brief.3" to "Det är vid grad 3 (betydande) som olyckorna samlas — förhållandena ser rimliga ut och underskattas lättast.",
    "lesson.m16.brief.4" to "Signaler på plats: snötäcket sätter sig med ett dovt «wumpf», färska sprickor uppstår, snökant och vindpackade flak bildas.",
    "lesson.m16.brief.5" to "Grupptaktik: håll avstånd, passera en i taget, placera en vakt på säker plats, planera reträttvägen.",

    // ---------- m17 Lägerledning ----------
    "lesson.m17.brief.1" to "Lägret har ett mål: behålla handlingsförmågan med minsta möjliga förbrukning. Värme, sömn, mat, vätska — faller en sak sjunker nästa dags kapacitet kraftigt.",
    "lesson.m17.brief.2" to "Plats: undvik lavinstråk och isfallsområden, stå inte under snökant eller över sprickor; välj plan, vindskyddad mark.",
    "lesson.m17.brief.3" to "Fördelning: bränsle, mat och syre portioneras per dag och en nödreserv hålls kvar. «Spara en portion» är inte överförsiktighet, det är garantin för säker nedstigning i alla lägen.",
    "lesson.m17.brief.4" to "Utrustningsvård: blöta kläder i sovsäcken, innerskor torkas, elektronik hålls varm på natten. Dessa tre småsaker avgör känslan i händer och fötter och batteriet nästa dag.",
    "lesson.m17.brief.5" to "Evakueringsplan: lägret är reträttens stödjepunkt och ska alltid vara «klart att packa ihop direkt».",

    // ---------- m18 7 000-metersberg ----------
    "lesson.m18.brief.1" to "Muztagh Ata 7 509 m (Akto, Xinjiang): «isfädernas fader». Långa snösluttningar, medelsvår teknik, men höga krav på acklimatisering och kondition; Kinas främsta första 7 000-metersberg.",
    "lesson.m18.brief.2" to "Ama Dablam 6 812 m (Khumbu, Nepal): höjdmässigt ett 6 000-metersberg, men brant blandad klippa-snö-terräng och stark exponering gör svårigheten jämförbar med 7 000+ — ofta prövosten för 8 000-metersbergen.",
    "lesson.m18.brief.3" to "Lenin Peak 7 134 m (Pamir, gränsen Kirgizistan/Tadzjikistan): det relativt milda valet bland 7 000-metersbergen, ofta det första.",
    "lesson.m18.brief.4" to "Himlung 7 126 m (Nepal): blandning av snösluttningar och isväggar, ett populärt 7 000-metersmål i Nepal.",
    "lesson.m18.brief.5" to "7 000 m är en vattendelare: acklimatiseringen blir längre, väderfönstret smalare, reträtten svårare. Tekniken är inte längre enda tröskeln; omdöme, form och logistik räknas samtidigt.",

    // ---------- m19 Dödszonen ----------
    "lesson.m19.brief.1" to "Över 8 000 m börjar «dödszonen»: lufttrycket är ungefär en tredjedel av havsnivån och varje andetag ger mindre än en tredjedel av syremolekylerna.",
    "lesson.m19.brief.2" to "På den höjden kan kroppen inte stanna länge — även utan rörelse försämras den (viktnedgång, muskelförlust, sämre kognition).",
    "lesson.m19.brief.3" to "Det som oftast sviktar först är omdömet: hypoxin skadar högre hjärnfunktioner (räkna, väga, uppfatta risk) först, medan krafttappet kommer senare.",
    "lesson.m19.brief.4" to "Därav en hård regel: på 8 000 m, lita inte på «känslan» på plats, utan på listan och reglerna som skrevs i förväg.",
    "lesson.m19.brief.5" to "Riskerna på 8 000 m är inte bara höjdsjuka, utan också laviner, fall och hypotermi. Ofta är den egentliga orsaken att nedstigningen skedde för sent.",

    // ---------- m20 Syre ----------
    "lesson.m20.brief.1" to "Syre höjer syremättnaden, sänker risken för höjdsjuka och förbättrar handlingsförmåga och omdöme. På 8 000 m är det standardutrustning för säkerhet, inte «fusk».",
    "lesson.m20.brief.2" to "Systemet: flaska, regulator, flödesmätare, mask eller näskanyl. Vid klättring används oftast 2–4 L/min; räckvidden beror på volym och flöde.",
    "lesson.m20.brief.3" to "Kärnregeln är att räkna syret ordentligt: beräkna «upp + ner + nödreserv» separat, inte bara om det «räcker upp».",
    "lesson.m20.brief.4" to "Risken när syret tar slut är hög: kroppen har vant sig vid hög koncentration, och återgången till omgivningens partialtryck kan snabbt försämra tillståndet. Planen måste därför ha säkerhetsmarginal.",
    "lesson.m20.brief.5" to "Syre ändrar inte miljön, förkortar inte rutten och ersätter inte acklimatisering. Det höjer bara den fysiologiska gränsen tillfälligt.",

    // ---------- m21 Himalayas 8 000-metersberg ----------
    "lesson.m21.brief.1" to "I världen finns 14 berg över 8 000 m, alla i Himalaya och Karakoram, fördelade på Kina, Nepal, Indien och Pakistan.",
    "lesson.m21.brief.2" to "Den här lektionen tar upp de tio i Himalaya: Everest, Kangchenjunga, Lhotse, Makalu, Cho Oyu, Nanga Parbat, Dhaulagiri, Manaslu, Annapurna och Shishapangma.",
    "lesson.m21.brief.3" to "Everest 8 848 m: världens högsta berg och det mest kommersiellt utvecklade; men «utvecklat» betyder inte «låg risk».",
    "lesson.m21.brief.4" to "Annapurna I 8 091 m: första bestigna 8 000-meterberget (1950) och samtidigt ett av de berg med högst dödlighet — först är inte lättast.",
    "lesson.m21.brief.5" to "Shishapangma 8 027 m: det enda 8 000-meterberget helt på kinesiskt territorium (Tibet) och det sista av de fjorton att bestigas (1964, kinesisk expedition).",

    // ---------- m22 Karakorams 8 000-metersberg ----------
    "lesson.m22.brief.1" to "Karakoram har fyra 8 000-metersberg: K2, Gasherbrum I, Gasherbrum II och Broad Peak — alla vid gränsen mellan Kina och Pakistan.",
    "lesson.m22.brief.2" to "K2 (8 611 m): världens näst högsta berg, anses vara ett av de mest tekniska och dödligaste 8 000-meterbergen, «klättrarnas berg».",
    "lesson.m22.brief.3" to "Broad Peak (8 051 m), även K3: relativt öppen terräng men mycket snö; underskattades länge för att det ansågs «lätt».",
    "lesson.m22.brief.4" to "Den stora skillnaden mot Himalaya är klimatet: Karakoram påverkas tydligare av västvindarna, väderfönster och nederbördsmönster skiljer sig helt från Everestområdet.",
    "lesson.m22.brief.5" to "Ser man de fjorton tillsammans kommer en central slutsats: svårighetsskillnaderna beror mest på teknisk terräng, klimat och logistik, inte på höjdordningen.",

    // ---------- m23 Grundprov ----------
    "lesson.m23.brief.1" to "Lektionen prövar den röda tråden: grunder, miljö, utrustning, klädsel, gång och självstopp med isyxa.",
    "lesson.m23.brief.2" to "Provet mäter inte inlärning utantill utan förmågan att koppla: utifrån en situation ska du gå från miljöbedömning till val av utrustning och vidare till teknisk rörelse.",
    "lesson.m23.brief.3" to "Tips: vid osäker fråga, gå tillbaka till den grundläggande orsakskedjan — lågt tryck → lågt syrepartialtryck → acklimatisering tar tid. Mycket kan härledas därifrån.",

    // ---------- m24 Avancerat prov ----------
    "lesson.m24.brief.1" to "Lektionen prövar den röda tråden: rep och säkring, sprickor, höjdmedicin, laviner och räddningsbeslut.",
    "lesson.m24.brief.2" to "Dessa ämnen har en sak gemensamt: de används först efter att problemet uppstått. Därför mäts inte «vet jag», utan «kan jag utföra det under press».",
    "lesson.m24.brief.3" to "Efter lektionen har du gått hela vägen från nybörjare på 5 000 m till slutprovet på 8 000 m — men kom ihåg: teori är inte förmåga i fält. Varje teknisk färdighet måste bedömas av en instruktör.",

    // ---------- m25 Etik i fjällen ----------
    "lesson.m25.brief.1" to "På höjd är två saker viktigare än kondition: att tala sanning och att inte pressa. Det är inte en attitydfråga — hypoxin träffar omdömet först, så «jag tror jag klarar det» ska diskonteras på höjd.",
    "lesson.m25.brief.2" to "«Nu är vi ändå här» är den dyraste meningen i bergen: den gör redan investerad tid till skäl att fortsätta riskera. Berget sänker inte risken för att du lagt ner mycket.",
    "lesson.m25.brief.3" to "När kroppen signalerar är första steget inte att «bita ihop», utan att stanna, observera och ärligt säga det till kamraten eller guiden. Guiden kan bara besluta om han vet.",
    "lesson.m25.brief.4" to "Långsamt är snabbt: ett jämnt, hållbart tempo sparar tid och är säkrare än upprepade spurtar — det beskriver en lag om energiomsättningen, inte en attityd.",
    "lesson.m25.brief.5" to "Meningsskiljaktigheter måste sägas högt. Den tysta minoriteten dyker alltid upp i olycksutredningar; att hysa en invändning och ändå utföra går att förena."
)
